content.text:
{
  "name": "通用SCPI函数发生器",
  "name_en": "Generic SCPI Function Generator",
  "manufacturer": "",
  "description": "用于与通用 SCPI 兼容函数发生器通信的仪器，可配置输出波形类型、频率、直流偏置和相位，在实验中用于产生电信号激励与测试波形。",
  "description_en": "An instrument for communicating with generic SCPI-compliant function generators. It can configure waveform type, frequency, DC offset, and phase for generating electrical stimulus and test waveforms in laboratory experiments.",
  "actions": [
    {
      "action_name": "auto-frequency",
      "description": "设置/获取输出频率",
      "description_en": "Set/get the output frequency"
    },
    {
      "action_name": "auto-function",
      "description": "设置/获取输出波形类型",
      "description_en": "Set/get the output waveform function"
    },
    {
      "action_name": "auto-offset",
      "description": "设置/获取输出直流偏置",
      "description_en": "Set/get the output DC offset"
    },
    {
      "action_name": "auto-phase",
      "description": "设置/获取输出相位",
      "description_en": "Set/get the output phase"
    }
  ],
  "tag_hints": [
    "function generator",
    "SCPI",
    "waveform output",
    "frequency control",
    "phase control",
    "DC offset"
  ]
}

